// Backlink monitor plan (weekly Monday 07:30; the first run of each month is the FULL run, the others are LIGHT): per site the window since the
// last check, the competitors (configured, else found once through DataForSEO Labs and kept), the brand names for mention search, the pages
// worth pitching (ladder top / published pages, case studies) and the existing prospects. Light runs only watch for lost and spammy links
// and stay quiet unless something important happened.
// ---- shared by the monitors (AI Visibility Tracker, Backlink Monitor, Audit Scheduler; inlined by the build): which sites, with which settings ----
// Sites = the Data Table seo_sites ("Track my site") + every domain with a keyword ladder; settings per site from seo_monitors (defaults: everything on).
// On demand (Manual Run with { domain | site_id }) one site runs even when its weekly / monthly monitor is off; an untracked domain is checked ad hoc
// with the trigger's country, e-mail and callback.
let trigger = {}; try { const t = $('Manual Run').first(); trigger = (t && t.json) || {}; } catch (e) {}
if (trigger.body && typeof trigger.body === 'object') trigger = { ...trigger, ...trigger.body };
const rowsOf = (name) => { try { return $(name).all().map(i => i.json).filter(r => r && typeof r === 'object' && !r.error && Object.keys(r).length); } catch (e) { return []; } };
const normD = (x) => String(x || '').toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[\/?#].*$/, '');
const siteIdFor = (d) => 'site_' + d.replace(/[^a-z0-9]+/g, '-');
const listOf = (v) => (Array.isArray(v) ? v : String(v || '').split(/[\n,;]+/)).map(x => String(x).trim()).filter(Boolean);
const flag = (v, dflt) => (v === undefined || v === null || v === '') ? dflt : !(v === false || /^(false|0|no|off)$/i.test(String(v)));
const DEFAULT_ENGINES = ['chatgpt', 'perplexity', 'gemini', 'claude', 'ai_overview', 'ai_mode'];
function monitorSites(kind) {   // kind: 'ai' | 'backlinks' | 'audit'
  const sites = rowsOf('Load Sites').filter(r => r.site_id && r.domain), ladders = rowsOf('Load Ladders').filter(r => r.domain), mons = rowsOf('Load Monitors'), profiles = rowsOf('Load Profiles');
  const byDomain = new Map();
  for (const s of sites) { const d = normD(s.domain); if (d && !byDomain.has(d)) byDomain.set(d, { ...s, domain: d, keywords: listOf(s.keywords).map(k => k.toLowerCase()), virtual: false }); }
  for (const l of ladders) { const d = normD(l.domain); if (d && !byDomain.has(d)) byDomain.set(d, { site_id: siteIdFor(d), domain: d, country: l.country || '', location_code: Number(l.location_code) || 0, language_code: l.language_code || 'en', email: l.email || '', callback_url: l.callback_url || '', keywords: [], status: 'active', source: 'ladder', virtual: true }); }
  for (const s of byDomain.values()) { if (s.email && s.callback_url) continue; const l = ladders.find(l => normD(l.domain) === s.domain && (l.email || l.callback_url)); if (l) { s.email = s.email || l.email || ''; s.callback_url = s.callback_url || l.callback_url || ''; } }
  const want = normD(trigger.domain) || String(trigger.site_id || '').trim();
  let list = [...byDomain.values()];
  if (want) {
    list = list.filter(s => s.domain === want || s.site_id === want);
    if (!list.length && normD(trigger.domain)) list = [{ site_id: siteIdFor(normD(trigger.domain)), domain: normD(trigger.domain), country: trigger.country || '', location_code: Number(trigger.location_code) || 0, language_code: trigger.language_code || 'en', email: '', callback_url: '', keywords: [], status: 'active', source: 'adhoc', virtual: true, adhoc: true }];
  } else list = list.filter(s => String(s.status || 'active') !== 'paused');
  const out = list.map(s => {
    const m = mons.find(x => x.site_id === s.site_id) || {};
    const p = profiles.find(x => x.site_id === s.site_id) || {};
    const engines = listOf(m.ai_engines).map(e => e.toLowerCase()).filter(e => DEFAULT_ENGINES.includes(e));
    const settings = { ai_visibility: flag(m.ai_visibility, true), backlinks: flag(m.backlinks, true), audit_monthly: flag(m.audit_monthly, true), engines: engines.length ? engines : DEFAULT_ENGINES,
      prompts_max: Math.min(15, Math.max(3, Number(m.ai_prompts_max) || 8)), audit_pages: Math.min(1000, Math.max(50, Number(m.audit_pages) || 200)), audit_js: flag(m.audit_js, false),
      competitors: [...new Set([...listOf(m.competitors), ...listOf(trigger.competitors)].map(normD).filter(d => d && d !== s.domain))].slice(0, 5),
      brand_names: [...new Set([...listOf(m.brand_names), ...listOf(trigger.brand_names), p.business_name || ''].map(x => String(x).trim()).filter(Boolean))], stored: !!m.site_id };
    const o = { ...s, settings, profile: { business_name: p.business_name || '', business_type: p.business_type || '', city: p.city || '', phone: p.phone || '', street_address: p.street_address || '', author_name: p.author_name || '' } };
    if (want) { if (trigger.email) o.email = trigger.email; if (trigger.callback_url) o.callback_url = trigger.callback_url; if (trigger.country) o.country = trigger.country; if (Number(trigger.location_code)) o.location_code = Number(trigger.location_code); if (trigger.language_code) o.language_code = trigger.language_code; }
    o.request_id = String(trigger.request_id || s.request_id || '');
    return o;
  });
  const flagOf = { ai: 'ai_visibility', backlinks: 'backlinks', audit: 'audit_monthly' }[kind];
  return { list: want ? out : out.filter(s => s.settings[flagOf]), on_demand: !!want, want, trigger, total: byDomain.size };
}

const CONFIG = { max_sites_per_run: 15, first_lookback_days: 30 };
const { list, on_demand, want, total } = monitorSites('backlinks');   // `trigger` comes from the shared snippet
if (!list.length) return [{ json: { nothing_to_do: true, reason: on_demand ? 'no site matches "' + want + '"' : (total ? 'the backlink monitor is switched off for every site' : 'no sites yet (register one through "Track my site" or plan a keyword ladder)') } }];
const snaps = rowsOf('Load Backlink Snapshots'), prospects = rowsOf('Load Link Prospects'), ladders = rowsOf('Load Ladders'), logs = rowsOf('Load Content Log'), cases = rowsOf('Load Case Studies');
const now = new Date(); const iso = now.toISOString(); const month = iso.slice(0, 7);
const dfs = (d) => new Date(d).toISOString().replace('T', ' ').slice(0, 19) + ' +00:00';
const parse = (t, d) => { try { return JSON.parse(t || ''); } catch (e) { return d; } };
return list.slice(0, CONFIG.max_sites_per_run).map(s => {
  const mine = snaps.filter(x => x.site_id === s.site_id).sort((a, b) => String(b.checked_at).localeCompare(String(a.checked_at)));
  const last = mine[0] || null, lastFull = mine.find(x => x.mode === 'full') || null;
  const mode = on_demand ? (trigger.light ? 'light' : 'full') : ((!lastFull || String(lastFull.checked_at).slice(0, 7) !== month) ? 'full' : 'light');
  const since = last ? dfs(last.checked_at) : dfs(now.getTime() - CONFIG.first_lookback_days * 864e5);
  const kept = lastFull ? (parse(lastFull.competitors_json, []) || []).map(c => c.domain).filter(Boolean) : [];
  const competitors = (s.settings.competitors.length ? s.settings.competitors : kept).slice(0, 3);
  const lad = ladders.filter(l => normD(l.domain) === s.domain && l.target_url && (l.status === 'published' || l.page_exists === true || l.page_exists === 'true'));
  const assets = [...lad.sort((a, b) => (Number(b.rung) || 0) - (Number(a.rung) || 0)).map(l => ({ url: l.target_url, title: l.keyword, kind: Number(l.rung) === 4 ? 'hub page' : 'guide' })),
    ...cases.filter(c => c.site_id === s.site_id && c.page_url).map(c => ({ url: c.page_url, title: c.title, kind: 'case study' })),
    ...logs.filter(l => normD(l.domain) === s.domain && l.published_url).map(l => ({ url: l.published_url, title: l.keyword, kind: 'article' }))].filter((a, i, arr) => arr.findIndex(b => b.url === a.url) === i).slice(0, 8);
  const brand = [...new Set([s.domain, s.profile.business_name].filter(b => b && (b.includes('.') || b.split(/\s+/).length >= 2 || b.length >= 8)))];
  return { json: { site_id: s.site_id, domain: s.domain, country: s.country || '', location_code: Number(s.location_code) || 2840, language_code: s.language_code || 'en', email: s.email || '', callback_url: s.callback_url || '', request_id: s.request_id || '',
    on_demand, adhoc: !!s.adhoc, mode, since, competitors, need_competitors: mode === 'full' && !competitors.length, business_name: s.profile.business_name || '', brand_names: brand, assets,
    previous: last ? { checked_at: last.checked_at, mode: last.mode, rank: Number(last.rank) || 0, backlinks: Number(last.backlinks) || 0, referring_domains: Number(last.referring_domains) || 0, spam_score: Number(last.spam_score) || 0, broken_backlinks: Number(last.broken_backlinks) || 0 } : null,
    existing_prospects: prospects.filter(p => p.site_id === s.site_id).length, checked_at: iso } };
});

// Backlink requests per site (DataForSEO Backlinks API, $0.024 per request + $0.000036 per row, measured 2026-10-02). Every run: summary,
// links lost since the last check, new links since the last check. Full runs add: links pointing to broken pages (reclaim), the referring
// domains (to see which prospects linked), 12 months of history, unlinked brand mentions (Content Analysis) and, once, the competitors.
const API = 'https://api.dataforseo.com/v3/';
const plans = $('BL Plan').all().map(i => i.json).filter(p => !p.nothing_to_do);
const out = [];
const add = (p, kind, endpoint, body) => out.push({ json: { site_id: p.site_id, domain: p.domain, kind, endpoint: API + endpoint, body: [body] } });
const ymd = (d) => d.toISOString().slice(0, 10);
for (const p of plans) {
  const t = p.domain;
  add(p, 'summary', 'backlinks/summary/live', { target: t, include_subdomains: true, internal_list_limit: 10, backlinks_status_type: 'live' });
  add(p, 'lost', 'backlinks/backlinks/live', { target: t, mode: 'as_is', backlinks_status_type: 'lost', filters: ['last_seen', '>', p.since], order_by: ['domain_from_rank,desc'], limit: 100 });
  add(p, 'new', 'backlinks/backlinks/live', { target: t, mode: 'one_per_domain', backlinks_status_type: 'live', filters: ['first_seen', '>', p.since], order_by: ['domain_from_rank,desc'], limit: 100 });
  if (p.mode !== 'full') continue;
  add(p, 'broken', 'backlinks/backlinks/live', { target: t, mode: 'as_is', filters: ['is_broken', '=', true], order_by: ['domain_from_rank,desc'], limit: 50 });
  add(p, 'refdomains', 'backlinks/referring_domains/live', { target: t, backlinks_status_type: 'live', order_by: ['rank,desc'], limit: 500 });
  add(p, 'timeseries', 'backlinks/timeseries_summary/live', { target: t, date_from: ymd(new Date(Date.now() - 365 * 864e5)), date_to: ymd(new Date()), group_range: 'month' });
  for (const b of p.brand_names) add(p, 'mentions', 'content_analysis/search/live', { keyword: b, search_mode: 'as_is', limit: 50 });
  if (p.need_competitors) add(p, 'competitors', 'dataforseo_labs/google/competitors_domain/live', { target: t, location_code: p.location_code, language_code: p.language_code, limit: 10, exclude_top_domains: true });
}
return out.length ? out : [{ json: { skip: true } }];

// Link gap (full runs): the domains that link to at least one competitor but not to you (backlinks/domain_intersection; the linking domain is the
// item's `target` field), one request per site.
// Competitors: configured, kept from earlier runs, or picked now from the Labs competitors (big platforms and the site itself excluded).
const API = 'https://api.dataforseo.com/v3/';
const plans = $('BL Plan').all().map(i => i.json).filter(p => !p.nothing_to_do);
const reqs = $('BL Requests').all().map(i => i.json); const resps = $('Run BL Requests').all().map(i => i.json || {});
const BIG = /(^|\.)(google|youtube|facebook|linkedin|wikipedia|amazon|apple|microsoft|reddit|quora|instagram|x|twitter|tiktok|medium|github|indeed|glassdoor|gov)\./i;
const out = [];
for (const p of plans) {
  let comps = [...p.competitors];
  if (!comps.length) { const i = reqs.findIndex(r => r.site_id === p.site_id && r.kind === 'competitors'); const items = i >= 0 ? (((resps[i].tasks || [])[0] || {}).result || [{}])[0]?.items || [] : [];
    comps = items.map(x => String(x.domain || '').replace(/^www\./, '')).filter(d => d && d !== p.domain && !BIG.test(d + '.') && !/\.gov(\.|$)/.test(d)).slice(0, 3); }
  if (p.mode !== 'full' || !comps.length) continue;
  const targets = {}; comps.forEach((c, i) => { targets[String(i + 1)] = c; });
  out.push({ json: { site_id: p.site_id, domain: p.domain, kind: 'gap', competitors: comps, endpoint: API + 'backlinks/domain_intersection/live', body: [{ targets, exclude_targets: [p.domain], intersection_mode: 'partial', limit: 100, order_by: ['1.rank,desc'] }] } });   // partial = links to at least one competitor (verified live 2026-10-02)
}
return out.length ? out : [{ json: { skip: true } }];

// Per site: link profile now vs the last check, links lost (important ones = alert), new links (spammy ones flagged), links pointing to broken
// pages on the site (reclaim with a redirect), 12 months of history, unlinked brand mentions, the link gap (domains linking to competitors, not
// to you), alerts and the prospect candidates (gap / mention / lost / reclaim). Rank and spam score are DataForSEO's 0-1000 and 0-100 scales.
const plans = $('BL Plan').all().map(i => i.json).filter(p => !p.nothing_to_do);
const reqs = $('BL Requests').all().map(i => i.json); const resps = $('Run BL Requests').all().map(i => i.json || {});
let greqs = [], gresps = []; try { greqs = $('Gap Requests').all().map(i => i.json); gresps = $('Run Gap Requests').all().map(i => i.json || {}); } catch (e) {}
const SPAM_WORDS = /\b(pbn|buy (?:cheap )?backlinks?|backlinks? (?:service|package)|link ?farm|casino|betting|slots?|porn|xxx|viagra|cialis|payday|escort|essay writing)\b/i;
const BIG = /(^|\.)(google|youtube|facebook|linkedin|wikipedia|amazon|apple|microsoft|reddit|quora|instagram|twitter|x|tiktok|medium|github|pinterest|blogspot|wordpress|tumblr)\.[a-z.]+$/i;
const result = (rs, i) => { const t = ((rs[i] || {}).tasks || [])[0] || {}; return { ok: t.status_code === 20000, res: (t.result || [])[0] || null, cost: Number(t.cost) || 0, error: t.status_code && t.status_code !== 20000 ? t.status_message : ((rs[i] || {}).error ? String((rs[i].error.message || rs[i].error)).slice(0, 160) : null) }; };
const pathOf = (u) => String(u || '').replace(/^https?:\/\/[^\/]+/i, '') || '/';
const toks = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').split(' ').filter(t => t.length > 2);
return plans.map(p => {
  const get = (kind) => { const out = []; reqs.forEach((r, i) => { if (r.site_id === p.site_id && r.kind === kind) out.push(result(resps, i)); }); return out; };
  const one = (kind) => get(kind)[0] || { ok: false, res: null, cost: 0, error: 'not requested' };
  const cost = reqs.reduce((s, r, i) => s + (r.site_id === p.site_id ? result(resps, i).cost : 0), 0) + greqs.reduce((s, r, i) => s + (r.site_id === p.site_id ? result(gresps, i).cost : 0), 0);
  const S = one('summary'); const sm = S.res || {};
  const summary = { rank: Number(sm.rank) || 0, backlinks: Number(sm.backlinks) || 0, referring_domains: Number(sm.referring_domains) || 0, referring_domains_nofollow: Number(sm.referring_domains_nofollow) || 0, spam_score: Number(sm.backlinks_spam_score) || 0, broken_backlinks: Number(sm.broken_backlinks) || 0, broken_pages: Number(sm.broken_pages) || 0, available: S.ok, error: S.error };
  const spamOf = (x) => Number(x.backlink_spam_score) >= 50 || SPAM_WORDS.test(String(x.anchor || '') + ' ' + String(x.page_from_title || ''));
  const link = (x) => ({ from_domain: String(x.domain_from || '').replace(/^www\./, ''), from_url: x.url_from || '', to_url: x.url_to || '', anchor: String(x.anchor || '').slice(0, 120), dofollow: !!x.dofollow, domain_rank: Number(x.domain_from_rank) || 0, page_rank: Number(x.page_from_rank) || 0, spam: Number(x.backlink_spam_score) || 0, first_seen: String(x.first_seen || '').slice(0, 10), last_seen: String(x.last_seen || '').slice(0, 10), title: String(x.page_from_title || '').slice(0, 120) });
  const lost = ((one('lost').res || {}).items || []).map(link);
  const isImportant = (l) => l.spam < 40 && (l.domain_rank >= 150 || l.page_rank >= 100 || (l.dofollow && l.domain_rank >= 80));
  const important_lost = lost.filter(isImportant);
  const news = ((one('new').res || {}).items || []).map(x => ({ ...link(x), spammy: spamOf(x) }));
  const spammy = news.filter(x => x.spammy);
  // reclaim: links that point to broken pages here -> 301 to the closest live page
  const live = [...p.assets.map(a => a.url), 'https://' + p.domain + '/'];
  const suggest = (u) => { const t = new Set(toks(pathOf(u))); let best = live[live.length - 1], score = 0; for (const c of live) { const s = toks(pathOf(c)).filter(x => t.has(x)).length; if (s > score) { score = s; best = c; } } return best; };
  const brokenLinks = ((one('broken').res || {}).items || []).map(x => ({ ...link(x), status: Number(x.url_to_status_code) || null }));
  const reclaimMap = new Map();
  for (const b of brokenLinks) { const k = b.to_url; const r = reclaimMap.get(k) || { broken_url: k, status: b.status, links: 0, domains: new Set(), redirect_to: suggest(k) }; r.links++; r.domains.add(b.from_domain); reclaimMap.set(k, r); }
  const reclaim = [...reclaimMap.values()].map(r => ({ ...r, domains: [...r.domains].slice(0, 8) })).sort((a, b) => b.links - a.links).slice(0, 20);
  const refdomains = new Set(((one('refdomains').res || {}).items || []).map(x => String(x.domain || '').replace(/^www\./, '')).filter(Boolean));
  const ts = ((one('timeseries').res || {}).items || []).map(x => ({ month: String(x.date || '').slice(0, 7), backlinks: Number(x.backlinks) || 0, referring_domains: Number(x.referring_domains) || 0, rank: Number(x.rank) || 0 }));
  // unlinked mentions: pages naming the brand on a domain that does not link to you
  const brandRe = p.brand_names.map(b => new RegExp(String(b).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i'));
  const mentions = [];
  for (const m of get('mentions')) for (const x of ((m.res || {}).items || [])) { const d = String(x.domain || '').replace(/^www\./, ''); const ci = x.content_info || {}; const txt = (ci.title || '') + ' ' + (ci.snippet || '');
    if (!d || d === p.domain || d.endsWith('.' + p.domain) || refdomains.has(d) || BIG.test(d) || !brandRe.some(re => re.test(txt)) || mentions.some(y => y.domain === d)) continue;
    mentions.push({ domain: d, url: x.url || '', title: String(ci.title || '').slice(0, 140), domain_rank: Number(x.domain_rank) || 0, spam: Number(x.spam_score) || 0 }); }
  // link gap
  const gi = greqs.findIndex(g => g.site_id === p.site_id); const G = gi >= 0 ? result(gresps, gi) : null; const competitors = gi >= 0 ? greqs[gi].competitors : p.competitors;
  const gap = ((G && G.res && G.res.items) || []).map(it => { const vals = Object.entries(it.domain_intersection || {}); const f = (vals[0] || [])[1] || {};
    return { domain: String(f.target || '').replace(/^www\./, ''), rank: Number(f.rank) || 0, spam: Number(f.backlinks_spam_score) || 0, links_to: vals.map(([k]) => competitors[Number(k) - 1]).filter(Boolean), backlinks: vals.reduce((s, [, v]) => s + (Number(v.backlinks) || 0), 0) }; })
    .filter(g => g.domain && g.spam < 30 && !BIG.test(g.domain) && !refdomains.has(g.domain) && g.domain !== p.domain).sort((a, b) => (b.links_to.length - a.links_to.length) || (b.rank - a.rank)).slice(0, 30);
  // alerts
  const prev = p.previous; const alerts = [];
  if (important_lost.length) alerts.push({ level: 'high', text: important_lost.length + ' important link(s) lost: ' + important_lost.slice(0, 3).map(l => l.from_domain + ' (authority ' + l.domain_rank + ')').join(', ') + '.' });
  if (spammy.length >= 3) alerts.push({ level: 'medium', text: spammy.length + ' new spammy links (PBN / link-farm pages) since ' + p.since.slice(0, 10) + '.' });
  if (prev && summary.available && prev.spam_score && summary.spam_score - prev.spam_score >= 15) alerts.push({ level: 'medium', text: 'Link spam score rose from ' + prev.spam_score + ' to ' + summary.spam_score + '.' });
  if (prev && summary.available && prev.referring_domains >= 10 && summary.referring_domains < prev.referring_domains * 0.9) alerts.push({ level: 'medium', text: 'Referring domains fell from ' + prev.referring_domains + ' to ' + summary.referring_domains + '.' });
  if (reclaim.length) alerts.push({ level: 'low', text: reclaim.reduce((s, r) => s + r.links, 0) + ' link(s) point to ' + reclaim.length + ' broken page(s): redirect them to keep the value.' });
  const deliver = p.mode === 'full' || p.on_demand || alerts.some(a => a.level === 'high' || a.level === 'medium');
  // disavow candidates (review, do not upload blindly: Google ignores most spam on its own)
  const disavow = [...new Set([...spammy.filter(x => x.spam >= 60 || SPAM_WORDS.test(x.anchor + ' ' + x.title)).map(x => x.from_domain)])];
  const disavow_text = disavow.length ? '# Disavow candidates for ' + p.domain + ' (' + p.checked_at.slice(0, 10) + ')\n# Review before uploading at https://search.google.com/search-console/disavow-links — Google ignores most spam links on its own;\n# disavow only for a manual action or a clear paid-link pattern you did not create.\n' + disavow.map(d => 'domain:' + d).join('\n') + '\n' : '';
  const candidates = [
    ...important_lost.map(l => ({ prospect_domain: l.from_domain, type: 'lost', rank: l.domain_rank, spam_score: l.spam, detail: 'Linked to ' + pathOf(l.to_url) + ' from ' + l.from_url + ' until ' + l.last_seen, source_url: l.from_url, target_url: l.to_url })),
    ...reclaim.flatMap(r => r.domains.slice(0, 3).map(d => ({ prospect_domain: d, type: 'reclaim', rank: 0, spam_score: 0, detail: 'Links to ' + pathOf(r.broken_url) + ' (HTTP ' + (r.status || 'error') + '): 301-redirect it to ' + pathOf(r.redirect_to), source_url: '', target_url: r.redirect_to }))),
    ...mentions.slice(0, 10).map(m => ({ prospect_domain: m.domain, type: 'mention', rank: m.domain_rank, spam_score: m.spam, detail: 'Mentions you without a link: ' + m.title, source_url: m.url, target_url: 'https://' + p.domain + '/' })),
    ...gap.slice(0, 25).map(g => ({ prospect_domain: g.domain, type: 'gap', rank: g.rank, spam_score: g.spam, detail: 'Links to ' + g.links_to.join(', ') + ' (' + g.backlinks + ' links), not to you', source_url: '', target_url: (p.assets[0] || {}).url || '' }))];
  return { json: { ...p, competitors, summary, lost, important_lost, new_links: news, spammy, reclaim, refdomains: [...refdomains].slice(0, 500), timeseries: ts, mentions, gap, alerts, deliver, disavow_text, candidates, gap_error: G && !G.ok ? G.error : null, cost_usd: +cost.toFixed(4) } };
});

// Up to 8 new prospects per site get an outreach draft (Claude, low effort): lost links first (ask to restore), then unlinked mentions
// (ask for the link), then link-gap and AI-source domains (pitch a page worth linking to). Prospects that already have a draft are skipped.
const sites = $('Parse Backlinks').all().map(i => i.json);
let existing = []; try { existing = $('Load Link Prospects').all().map(i => i.json).filter(x => x && x.prospect_domain); } catch (e) {}
const ORDER = { lost: 0, mention: 1, gap: 2, ai_source: 3 };
const jobs = [];
for (const s of sites) {
  const aiSources = existing.filter(x => x.site_id === s.site_id && x.type === 'ai_source' && !x.outreach_body && x.status === 'new').map(x => ({ prospect_domain: x.prospect_domain, type: 'ai_source', rank: Number(x.rank) || 0, detail: x.detail, source_url: '', target_url: '' }));
  const todo = [...s.candidates.filter(c => c.type !== 'reclaim'), ...aiSources]
    .filter(c => { const e = existing.find(x => x.site_id === s.site_id && x.prospect_domain === c.prospect_domain && x.type === c.type); return !e || (!e.outreach_body && (e.status || 'new') === 'new'); })
    .sort((a, b) => (ORDER[a.type] - ORDER[b.type]) || (b.rank - a.rank)).slice(0, 8);
  if (s.mode === 'full' && todo.length) jobs.push({ json: { site_id: s.site_id, domain: s.domain, business_name: s.business_name || s.domain, assets: s.assets, prospects: todo } });
}
return jobs.length ? jobs : [{ json: { skip: true } }];

// The link-prospect pipeline (seo_link_prospects, upsert by site + prospect domain + type; exact columns): this run's candidates merged with
// the stored rows (status, notes and drafts kept), outreach drafts attached, and prospects that now link to you marked "won" automatically.
const sites = $('Parse Backlinks').all().map(i => i.json);
let existing = []; try { existing = $('Load Link Prospects').all().map(i => i.json).filter(x => x && x.prospect_domain); } catch (e) {}
let jobs = [], outs = []; try { jobs = $('Outreach Jobs').all().map(i => i.json).filter(j => !j.skip); outs = $('Outreach Writer').all().map(i => i.json); } catch (e) {}
const parse = (raw) => { if (raw && typeof raw === 'object') return raw; const s = String(raw || '').replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, ''); try { return JSON.parse(s); } catch (e) { const a = s.indexOf('{'), b = s.lastIndexOf('}'); try { return JSON.parse(s.slice(a, b + 1)); } catch (e2) { return null; } } };
const rows = [];
for (const s of sites) {
  const now = s.checked_at; const ji = jobs.findIndex(j => j.site_id === s.site_id);
  const drafts = ji >= 0 && outs[ji] && !outs[ji].error ? ((parse(outs[ji].output) || {}).drafts || []) : [];
  const linking = new Set([...s.refdomains, ...s.new_links.filter(l => !l.spammy).map(l => l.from_domain)]);
  const key = (x) => x.prospect_domain + '|' + x.type;
  const mine = new Map(existing.filter(x => x.site_id === s.site_id).map(x => [key(x), x]));
  const seen = new Set();
  const emit = (c, old) => { const d = drafts.find(x => String(x.prospect_domain || '').toLowerCase() === c.prospect_domain && !old.outreach_body);
    const won = c.type !== 'reclaim' && linking.has(c.prospect_domain) && (old.status || 'new') !== 'won';
    rows.push({ site_id: s.site_id, domain: s.domain, prospect_domain: c.prospect_domain, type: c.type, rank: Number(c.rank ?? old.rank) || 0, spam_score: Number(c.spam_score ?? old.spam_score) || 0, detail: String(c.detail || old.detail || '').slice(0, 300),
      source_url: c.source_url || old.source_url || '', target_url: c.target_url || old.target_url || '', status: won ? 'won' : (old.status || 'new'), first_seen: old.first_seen || now, last_seen: c.fresh ? now : (old.last_seen || now),
      won_at: won ? now : (old.won_at || ''), outreach_subject: old.outreach_subject || (d ? String(d.subject || '').slice(0, 120) : ''), outreach_body: old.outreach_body || (d ? String(d.body || '').slice(0, 1500) : ''), note: old.note || '' }); };
  for (const c of s.candidates) { const k = key(c); if (seen.has(k)) continue; seen.add(k); emit({ ...c, fresh: true }, mine.get(k) || {}); }
  // stored prospects not seen this run: only touched when they now link (won) or a draft was written for them (ai_source)
  for (const [k, old] of mine) { if (seen.has(k)) continue; const won = old.type !== 'reclaim' && linking.has(old.prospect_domain) && old.status !== 'won'; const d = drafts.find(x => String(x.prospect_domain || '').toLowerCase() === old.prospect_domain && !old.outreach_body);
    if (won || d) { seen.add(k); emit({ prospect_domain: old.prospect_domain, type: old.type }, old); } }
}
return rows.length ? rows.map(r => ({ json: r })) : [{ json: { skip: true } }];

// One seo_backlink_snapshots row per site per run (exact columns); lists are kept short.
return $('Parse Backlinks').all().map(i => { const s = i.json; const J = (o) => JSON.stringify(o);
  return { json: { site_id: s.site_id, domain: s.domain, checked_at: s.checked_at, mode: s.mode, rank: s.summary.rank, backlinks: s.summary.backlinks, referring_domains: s.summary.referring_domains, referring_domains_nofollow: s.summary.referring_domains_nofollow,
    spam_score: s.summary.spam_score, broken_backlinks: s.summary.broken_backlinks, new_links: s.new_links.length, lost_links: s.lost.length, important_lost: s.important_lost.length, spammy_new: s.spammy.length,
    lost_json: J(s.important_lost.slice(0, 20)), new_json: J(s.new_links.filter(l => !l.spammy).slice(0, 20)), competitors_json: J(s.competitors.map(d => ({ domain: d }))), timeseries_json: J(s.timeseries), cost_usd: s.cost_usd } }; });

// Backlink report per site: monthly FULL report (profile vs last month, 12-month history, lost / new / spammy links, broken links to reclaim,
// link gap, unlinked mentions, the prospect pipeline with outreach drafts) or, on light weeks, a short ALERT e-mail when an important link was
// lost or spam arrived. Attachments: prospects.csv and, when needed, disavow-candidates.txt. Sites with nothing to report stay quiet.
// ---- shared report helpers (inlined by the build): the same look as the Site Tracker report ----
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const n = (v) => (Number(v) || 0).toLocaleString('en-GB');
const td = 'style="padding:4px 8px;border:1px solid #cbd5e1;font-size:13px;vertical-align:top"', th = 'style="padding:4px 8px;border:1px solid #cbd5e1;background:#f1f5f9;text-align:left;font-size:12px"';
const table = (headers, rows, empty) => rows.length ? '<table style="border-collapse:collapse;margin:6px 0;max-width:100%">' + '<tr>' + headers.map(h => '<th ' + th + '>' + esc(h) + '</th>').join('') + '</tr>' + rows.map(r => '<tr>' + r.map(c => '<td ' + td + '>' + c + '</td>').join('') + '</tr>').join('') + '</table>' : '<p style="color:#64748b;font-size:13px">' + esc(empty || 'nothing to show') + '</p>';
const tile = (label, value, delta, color) => '<td style="padding:8px 12px;border:1px solid #e2e8f0;min-width:110px;vertical-align:top"><div style="font-size:11px;color:#64748b;text-transform:uppercase">' + esc(label) + '</div><div style="font-size:20px;font-weight:700">' + value + '</div><div style="font-size:12px;color:' + (color || '#475569') + '">' + delta + '</div></td>';
const h3 = (t) => '<h3 style="margin:18px 0 4px;font-size:15px;color:#0f172a">' + esc(t) + '</h3>';
const p_ = (t, muted) => '<p style="margin:4px 0;font-size:13px' + (muted ? ';color:#64748b' : '') + '">' + t + '</p>';
const pathOf = (u) => { const p = String(u || '').replace(/^https?:\/\/[^\/]+/i, ''); return p || '/'; };
const link = (u, label) => u ? '<a href="' + esc(u) + '" style="color:#1d4ed8">' + esc(label || pathOf(u)) + '</a>' : '—';
const dpts = (v) => v == null ? '' : (v > 0 ? '<span style="color:#15803d">▲ ' + v + ' pts</span>' : v < 0 ? '<span style="color:#b91c1c">▼ ' + Math.abs(v) + ' pts</span>' : 'no change');
const briefBox = (b) => b ? '<div style="background:#f8fafc;border-left:4px solid #1d4ed8;padding:10px 12px;margin:8px 0"><div style="font-weight:700;font-size:15px">' + esc(b.headline) + '</div><p style="margin:6px 0 0;font-size:13px">' + esc(b.summary) + '</p></div>' : '';
const alertBox = (alerts) => (alerts || []).length ? '<div style="background:#fef2f2;border-left:4px solid #b91c1c;padding:8px 12px;margin:8px 0">' + alerts.map(a => '<div style="font-size:13px">⚠ ' + esc(a.text || a) + '</div>').join('') + '</div>' : '';
const wrapDoc = (title, body) => '<!DOCTYPE html><html><head><meta charset="utf-8"><title>' + esc(title) + '</title></head><body style="margin:24px">' + body + '</body></html>';
const b64 = (s) => Buffer.from(String(s), 'utf8').toString('base64');

const sites = $('Parse Backlinks').all().map(i => i.json);
let rows = []; try { rows = $('Prospect Rows').all().map(i => i.json).filter(r => !r.skip); } catch (e) {}
let stored = []; try { stored = $('Load Link Prospects').all().map(i => i.json).filter(x => x && x.prospect_domain); } catch (e) {}
const csvCell = (v) => '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"';
const TYPE = { lost: 'Lost link — ask to restore', mention: 'Unlinked mention — ask for the link', gap: 'Links to competitors', ai_source: 'Cited by AI answers', reclaim: 'Broken page — redirect' };
return sites.filter(s => s.deliver).map(s => {
  const S = s.summary, P = s.previous; const full = s.mode === 'full';
  const pipe = [...rows.filter(r => r.site_id === s.site_id), ...stored.filter(x => x.site_id === s.site_id && !rows.some(r => r.site_id === s.site_id && r.prospect_domain === x.prospect_domain && r.type === x.type))];
  const won = pipe.filter(r => r.status === 'won' && String(r.won_at || '').slice(0, 10) === s.checked_at.slice(0, 10));
  const counts = ['new', 'contacted', 'won', 'rejected', 'ignored'].map(st => st + ' ' + pipe.filter(r => (r.status || 'new') === st).length).join(' · ');
  const dv = (cur, prev) => P ? (cur - prev > 0 ? '<span style="color:#15803d">+' + n(cur - prev) + '</span>' : cur - prev < 0 ? '<span style="color:#b91c1c">' + n(cur - prev) + '</span>' : 'no change') : 'first check';
  let html = '<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif;color:#0f172a;max-width:900px">';
  html += '<h2 style="margin:0 0 2px;font-size:20px">' + (full ? 'Backlinks: ' : 'Backlink alert: ') + esc(s.domain) + '</h2>' + p_(esc(s.checked_at.slice(0, 10)) + ' · changes since ' + esc(s.since.slice(0, 10)) + (full ? ' · monthly report' : ' · weekly watch') + (s.on_demand ? ' · on-demand run' : ''), true);
  html += alertBox(s.alerts.filter(a => full || a.level !== 'low'));
  if (!S.available) html += p_('The Backlinks API returned no summary (' + esc(S.error || 'no data') + ').', true);
  html += '<table style="border-collapse:collapse;margin:8px 0"><tr>' + tile('Referring domains', n(S.referring_domains), P ? dv(S.referring_domains, P.referring_domains) : '') + tile('Backlinks', n(S.backlinks), P ? dv(S.backlinks, P.backlinks) : '') + tile('Authority (0-1000)', n(S.rank), P ? dv(S.rank, P.rank) : '') +
    tile('Spam score', S.spam_score + '/100', S.spam_score >= 40 ? '<span style="color:#b91c1c">high</span>' : 'ok') + tile('New / lost', n(s.new_links.length) + ' / ' + n(s.lost.length), 'since ' + s.since.slice(0, 10)) + '</tr></table>';
  if (s.important_lost.length || !full) html += h3('Important links lost') + table(['From', 'Authority', 'Pointed to', 'Last seen', 'What to do'], s.important_lost.map(l => [link(l.from_url, l.from_domain), n(l.domain_rank), esc(pathOf(l.to_url)), esc(l.last_seen), 'Ask the site owner to restore it (draft below); check the page still exists']), 'none');
  if (full) {
    if (s.timeseries.length) html += h3('Last 12 months') + table(['Month', 'Referring domains', 'Backlinks'], s.timeseries.slice(-12).map(t => [esc(t.month), n(t.referring_domains), n(t.backlinks)]));
    html += h3('New links') + table(['From', 'Authority', 'Anchor', 'First seen', ''], s.new_links.slice(0, 20).map(l => [link(l.from_url, l.from_domain), n(l.domain_rank), esc(l.anchor), esc(l.first_seen), l.spammy ? '<span style="color:#b91c1c">spammy</span>' : (l.dofollow ? 'follow' : 'nofollow')]), 'no new links since the last check');
    html += h3('Links to broken pages (reclaim with a 301)') + table(['Broken page', 'Status', 'Links', 'From', 'Redirect to'], s.reclaim.map(r => [esc(pathOf(r.broken_url)), esc(r.status || 'error'), n(r.links), esc(r.domains.join(', ')), link(r.redirect_to)]), 'none — every linked page works');
    html += h3('Link gap: sites that link to ' + (s.competitors.length ? s.competitors.join(', ') : 'your competitors') + ' but not to you') + (s.gap_error ? p_('Not available: ' + esc(s.gap_error), true) : '') + table(['Site', 'Authority', 'Links to'], s.gap.slice(0, 15).map(g => [esc(g.domain), n(g.rank), esc(g.links_to.join(', '))]), s.competitors.length ? 'no gap found' : 'no competitors known yet — add them with Site Admin action "monitors"');
    html += h3('Unlinked mentions') + table(['Site', 'Page', 'Authority'], s.mentions.map(m => [esc(m.domain), link(m.url, m.title || m.url), n(m.domain_rank)]), 'no pages found that name you without linking');
  }
  if (s.spammy.length) html += h3('Spammy new links') + table(['From', 'Spam', 'Anchor'], s.spammy.slice(0, 12).map(l => [esc(l.from_domain), n(l.spam), esc(l.anchor)])) + p_('Google ignores most spam links on its own. ' + (s.disavow_text ? 'A disavow list is attached for review: upload it only for a manual action or a paid-link pattern you did not create.' : ''), true);
  const drafts = pipe.filter(r => r.outreach_body && (r.status || 'new') === 'new').slice(0, 8);
  if (full || drafts.length) html += h3('Outreach — this month\'s drafts') + (drafts.length ? drafts.map(r => '<div style="border:1px solid #e2e8f0;padding:8px 10px;margin:6px 0"><div style="font-size:12px;color:#64748b">' + esc(r.prospect_domain) + ' · ' + esc(TYPE[r.type] || r.type) + ' · ' + esc(r.detail) + '</div><div style="font-weight:600;font-size:13px;margin-top:4px">' + esc(r.outreach_subject) + '</div><pre style="white-space:pre-wrap;font-family:inherit;font-size:13px;margin:4px 0 0">' + esc(r.outreach_body) + '</pre></div>').join('') : p_('No new drafts this month.', true));
  if (full) html += h3('Prospect pipeline') + p_(esc(counts) + (won.length ? ' · <b>won this month: ' + esc(won.map(w => w.prospect_domain).join(', ')) + '</b>' : '')) + p_('Mark a prospect as contacted / won / rejected with Site Admin action "prospect" (domain, prospect_domain, status). "Won" is also set automatically when the site starts linking to you. Full list: prospects.csv.', true);
  html += h3('How this works') + p_('Every Monday the monitor checks for lost and new links (alert e-mail only when something important happened); the first run of each month is the full report. Data: DataForSEO Backlinks and Content Analysis. Cost this run: $' + s.cost_usd.toFixed(2) + '.', true) + '</div>';
  const csv = ['site,prospect_domain,type,status,authority,spam,detail,source_url,target_url,first_seen,last_seen,won_at,outreach_subject,outreach_body,note'].concat(pipe.map(r => [r.domain, r.prospect_domain, r.type, r.status, r.rank, r.spam_score, r.detail, r.source_url, r.target_url, r.first_seen, r.last_seen, r.won_at, r.outreach_subject, r.outreach_body, r.note].map(csvCell).join(','))).join('\n');
  const subject = (full ? '[Backlinks] ' : '[Backlink alert] ') + s.domain + ' — ' + n(S.referring_domains) + ' referring domains' + (s.important_lost.length ? ' · ' + s.important_lost.length + ' important link(s) lost' : '') + (s.spammy.length >= 3 ? ' · ' + s.spammy.length + ' spammy' : '') + (won.length ? ' · ' + won.length + ' won' : '');
  const file_name = 'backlinks-' + s.domain.replace(/[^a-z0-9]+/gi, '-') + '-' + s.checked_at.slice(0, 10) + '.html';
  const binary = { data: { data: b64(wrapDoc(subject, html)), mimeType: 'text/html', fileName: file_name, fileExtension: 'html' } };
  if (full && pipe.length) binary.prospects_csv = { data: b64(csv), mimeType: 'text/csv', fileName: 'prospects-' + s.domain.replace(/[^a-z0-9]+/gi, '-') + '.csv', fileExtension: 'csv' };
  if (s.disavow_text) binary.disavow_txt = { data: b64(s.disavow_text), mimeType: 'text/plain', fileName: 'disavow-candidates-' + s.domain.replace(/[^a-z0-9]+/gi, '-') + '.txt', fileExtension: 'txt' };
  return { json: { ...s, refdomains: undefined, pipeline: { counts, won: won.map(w => w.prospect_domain), total: pipe.length }, prospects: pipe.slice(0, 60), subject, html, file_name, status: 'progress', stage: 'backlinks' }, binary };
});

// Attach the PDF (when the renderer succeeded) next to the report's other files, per site; a renderer failure never fails the run.
const src = $('Prepare PDF BL').all(); const got = $input.all();
return src.map((s, i) => { const g = got[i] || {}; const pdf = (g.binary && g.binary.pdf && !(g.json && g.json.error)) ? g.binary.pdf : null;
  const name = String(s.json.file_name || 'report.html').replace(/\.html?$/i, '') + '.pdf'; const binary = { ...(s.binary || {}) }; delete binary.html;
  if (pdf) binary.pdf = { ...pdf, fileName: name, mimeType: 'application/pdf', fileExtension: 'pdf' };
  return { json: { ...s.json, pdf_ready: !!pdf, pdf_file_name: pdf ? name : null }, binary }; });

// Callback payload per site for API callers: the backlink data, the PDF and the CSV / disavow files (bytes from n8n's binary store).
const items = $input.all(); const out = [];
const bytes = async (i, k, bin) => { try { const b = await this.helpers.getBinaryDataBuffer(i, k); return b && b.length ? b.toString('base64') : null; } catch (e) { return bin[k] && bin[k].data && String(bin[k].data).length > 20 ? bin[k].data : null; } };
for (let i = 0; i < items.length; i++) {
  const it = items[i]; const d = it.json || {}; const bin = it.binary || {}; const files = {};
  for (const k of ['pdf', 'prospects_csv', 'disavow_txt']) if (bin[k]) { const data = await bytes(i, k, bin); if (data) files[k] = { data, fileName: bin[k].fileName, mimeType: bin[k].mimeType }; }
  const { html, candidates, assets, ...rest } = d;
  out.push({ json: { ...rest, pdf: files.pdf || null, files } });
}
return out;
